import asyncio
from playwright.async_api import async_playwright
CSS=open('/home/claude/pan/style.css').read()+r"""
.pg{height:297mm}
.tl{display:grid;grid-template-columns:repeat(5,1fr);gap:6px;margin:6px 0}.tl>div{background:#fff;border:3px solid #140f1f;box-shadow:3px 3px 0 #140f1f;padding:7px;font-size:10.5px;line-height:1.4}.tl b{display:block;font-size:12.5px;margin-bottom:3px}.tl i{display:block;font-style:normal;background:#f7d64a;border:2px solid #140f1f;font-weight:800;font-size:10px;padding:1px 4px;margin-bottom:4px}
.say{background:#241a4a;color:#fff;border:3px solid #140f1f;box-shadow:4px 4px 0 #140f1f;padding:10px 12px;font-size:12.5px;line-height:1.5;margin:8px 0}
.src{font-size:8.5px;color:#5a5470;margin-top:4px;line-height:1.35}
"""
def page(n,title,body):return f'<section class="zpg"><div class="zsec"><span class="zttl zh2">{title}</span></div>{body}<div class="zfoot"><span>ZombieSafeHouse · Piano sponsor e investitori</span><span>{n}</span><span>INDZ · uso interno</span></div></section>'
def cap(t,b):return f'<div class="zcap"><h3>{t}</h3>{b}</div>'
def tab(rows,head):return '<table class="zt"><tr>'+''.join(f'<th>{h}</th>' for h in head)+'</tr>'+''.join('<tr>'+''.join(f'<td>{c}</td>' for c in r)+'</tr>' for r in rows)+'</table>'
def ul(L):return '<ul style="margin:4px 0 0 16px;padding:0;font-size:11.5px;line-height:1.5">'+''.join(f'<li>{x}</li>' for x in L)+'</ul>'
P=[]
P.append('''<section class="zpg cover"><div class="ct" style="margin-top:40mm"><span class="zttl zh1">ZombieSafeHouse</span><br><br><span class="zttl sub">Piano sponsor e investitori</span></div>
<div class="bub" style="margin-top:20mm">Come presentare l’app agli sponsor, quanto chiedere in base agli iscritti attivi entro 20 km, e a chi rivolgersi per i finanziamenti. Una base di lavoro da verificare con il pilota e con il commercialista.</div>
<div class="cf">INDZ · novembre 2026 · uso interno</div></section>''')
P.append(page(2,'Il piano in una pagina',cap('12 mesi, 5 fasi','<div class="tl"><div><i>settimane 1–2</i><b>Prepararsi</b>Materiali, contratto, account negozio di prova, lista contatti dall’app</div><div><i>mesi 1–3</i><b>Pilota</b>5–8 sponsor fondatori a Volta Mantovana, 300–500 iscritti</div><div><i>giorni 30·60·90</i><b>Dimostrare</b>Resoconto a ogni sponsor, passaggio al listino</div><div><i>mesi 4–9</i><b>Allargarsi</b>Comuni entro 20 km, agenti a provvigione, partner di categoria</div><div><i>dal mese 9</i><b>Marchi nazionali</b>Porte, serramenti, allarmi, assicurazioni</div></div>')
 +cap('In parallelo: i soldi',tab([['Mesi 1–3','Costituire la startup innovativa, preparare Smart&Start Italia, primi contatti con business angel del territorio'],['Mesi 4–6','Domanda Smart&Start con i numeri del pilota; incontri con acceleratori'],['Mesi 6–12','Round con business angel / equity crowdfunding; investitori strategici del settore']],['Quando','Cosa']))
 +cap('I numeri da raggiungere prima di chiedere soldi',ul(['500–1.000 iscritti attivi nella zona pilota','oltre il 20% degli iscritti che torna dopo 30 giorni','10 sponsor paganti, anche piccoli','un ricavo mensile ricorrente, anche modesto']))))
P.append(page(3,'Sponsor: chi, come, cosa dire',cap('Chi contattare (in ordine di interesse)',tab([['1','Fabbri, ferramenta, porte blindate','Sono i più legati ai punti deboli che l’app trova'],['2','Serramentisti, vetrai, grate','Finestre e portefinestre sono i punti deboli più comuni'],['3','Allarmi, videosorveglianza, elettricisti','Luci, sensori, telecamere'],['4','Assicurazioni casa','Chi valuta la casa è un cliente perfetto'],['5','Agenzie immobiliari','Indice di sicurezza della zona, case nel mondo del gioco']],['#','Categoria','Perché']))
 +cap('Dove trovarli: nell’app','<p>Apri la <b>Mappa</b> e tocca <b>🔧 attività</b>: l’app elenca le attività vere entro 20 km (ferramenta, fabbri, serramentisti, elettricisti…) con telefono, sito e indicazioni. È la tua lista contatti. Quando uno firma lo trasformi in sponsor dal pannello admin; quelli che non ti interessano li togli dalla mappa.</p>')
 +'<div class="say"><b>Il discorso in 30 secondi</b><br>“Le persone della zona valutano la sicurezza della loro casa con la nostra app. Quando scoprono un punto debole, l’app propone il tuo negozio con un codice sconto e un pulsante per chiederti un preventivo. Tu vedi nel tuo pannello quante persone ti hanno visto, quanti codici sono stati usati in cassa e chi ti ha chiesto un preventivo.”</div>'
 +cap('Le obiezioni e cosa rispondere',tab([['“Quanti utenti avete?”','“Stiamo partendo da qui: tu sei tra i fondatori, il prezzo resta bloccato per un anno e ci aiuti a portare iscritti con il QR in vetrina.”'],['“Non mi serve, ho già clienti.”','“Paghi anche solo a risultato: 15 € per preventivo ricevuto, 3 € per codice usato.”'],['“Lo faccio già sui social.”','“Qui ti trovano proprio quando scoprono di avere un problema alla porta o alle finestre.”']],['Obiezione','Risposta']))))
P.append(page(4,'Quanto chiedere: gli iscritti attivi entro 20 km',cap('L’unità di misura','<p><b>Iscritti attivi entro 20 km dal negozio</b>: persone che hanno aperto l’app almeno una volta nel mese e hanno la casa entro 20 km. Semplice, verificabile, cresce insieme all’app. Lo sponsor non paga un’app: paga le persone che può raggiungere.</p>')
 +cap('Canone mensile a scaglioni',tab([['fino a 500','29 €','59 €','129 €'],['500 – 2.000','49 €','99 €','249 €'],['2.000 – 5.000','99 €','199 €','449 €'],['5.000 – 20.000','199 €','349 €','799 €'],['oltre 20.000','su misura','su misura','su misura']],['Iscritti attivi entro 20 km','Vetrina','Vetrina Plus','Partner di categoria']))
 +cap('Più una parte a risultato',ul(['<b>15 €</b> per ogni preventivo ricevuto (già nel listino)','<b>3 €</b> per ogni codice sconto usato in cassa']))
 +cap('Regole',ul(['Scaglione ricalcolato ogni 3 mesi sul numero reale.','Chi firma nel pilota blocca il prezzo per 12 mesi.','Il negoziante vede i suoi numeri nel pannello negozio.','<b>Da aggiungere all’app</b>: il contatore “iscritti attivi entro 20 km” nel pannello negozio e nel pannello admin.']))
 +cap('Esempio','<p>Ferramenta a Volta Mantovana, Vetrina Plus, 1.200 iscritti attivi entro 20 km: 99 €/mese + 6 preventivi (90 €) + 20 codici usati (60 €) = <b>249 € nel mese</b>. È un esempio di calcolo, non una previsione.</p>')))
P.append(page(5,'Il pilota di 90 giorni, settimana per settimana',tab([['1–2','Lista di 15 attività dall’app; appuntamenti; materiali (una pagina, contratto, QR)'],['3–4','Firmare 5–8 sponsor fondatori; inserirli dal pannello admin; consegnare il QR da vetrina'],['5–8','Ogni sponsor porta iscritti (QR, volantino in cassa, post social). Tu: Piazza e Bacheca vive, rispondi a tutti'],['Giorno 30','Primo resoconto a ogni sponsor dal pannello negozio'],['9–12','Inviti tra vicini (150 🧱 a chi invita), missioni sui negozi sponsor'],['Giorno 60','Secondo resoconto; raccolta di 2–3 testimonianze'],['Giorno 90','Passaggio al listino; primo resoconto per gli investitori']],['Settimana','Cosa fare'])
 +cap('Cosa misurare ogni settimana',ul(['Iscritti nuovi e iscritti attivi entro 20 km','Quanti tornano dopo 7 e dopo 30 giorni','Visualizzazioni e schede aperte di ogni sponsor','Codici usati in cassa e preventivi','Inviti mandati e accettati']))))
P.append(page(6,'Investitori: a chi rivolgersi, in ordine',cap('1 · Fondi pubblici',ul(['<b>Smart&Start Italia (Invitalia)</b>: aggiornato con il Decreto MIMIT del 13 luglio 2026; finanziamento a tasso zero fino all’80% delle spese (fino al 90% in presenza di condizioni specifiche, es. team giovane o femminile), per piani di spesa tra 100.000 € e 1,5 milioni €, riservato alle startup innovative iscritte alla sezione speciale da non più di 60 mesi.','<b>Regione Lombardia</b> e <b>Camera di Commercio di Mantova</b>: bandi e voucher per il digitale (cambiano ogni anno: verificali con il commercialista).'])
 +'<p class="src">Fonti Smart&Start: MySolution (settembre 2026), Unioncamere, Tot (ottobre 2026).</p>')
 +cap('2 · Business angel',ul(['<b>IAG – Italian Angels for Growth</b>, <b>Club degli Investitori</b> (Torino), <b>IBAN – Italian Business Angels Network</b>.','Imprenditori del territorio tramite <b>Confindustria Mantova</b> e la Camera di Commercio: chi lavora in edilizia, serramenti, sicurezza o assicurazioni capisce subito l’app.']))
 +cap('3 · Incubatori e acceleratori',ul(['<b>PoliHub</b> (Politecnico di Milano), <b>Speed MI Up</b> (Bocconi e Camera di Commercio di Milano), <b>LVenture Group / LUISS EnLabs</b>, programmi di accelerazione di <b>CDP Venture Capital</b>.']))
 +cap('4 · Equity crowdfunding',ul(['<b>Mamacrowd</b>, <b>CrowdFundMe</b>: utenti e sponsor diventano piccoli soci, e la campagna fa pubblicità all’app.']))
 +cap('5 · Investitori strategici',ul(['Produttori di porte blindate e serramenti, aziende di allarmi, compagnie assicurative per la casa: possono investire o diventare sponsor nazionali.']))
 +'<p class="src">Non è una consulenza finanziaria o legale: per costituzione della startup, bandi e round fatti seguire da un commercialista esperto di startup innovative.</p>'))
P.append(page(7,'Lista di controllo',tab([[x,'☐'] for x in ['Costituire la startup innovativa (commercialista)','Una pagina per gli sponsor + contratto + QR da vetrina','Lista di 15 attività dall’app (🔧 attività della zona)','5–8 sponsor fondatori firmati e inseriti dal pannello admin','Contatore “iscritti attivi entro 20 km” nell’app (da fare)','Resoconto a 30, 60, 90 giorni per ogni sponsor','Pubblicazione su Google Play e App Store','Domanda Smart&Start Italia con i numeri del pilota','Incontri con business angel del territorio','Valutare una campagna di equity crowdfunding']],['Cosa','Fatto'])))
html=f'<!DOCTYPE html><html><head><meta charset="utf-8"><style>{CSS}</style></head><body>{"".join(P)}</body></html>'
open('/home/claude/piano/p.html','w',encoding='utf-8').write(html)
async def main():
    async with async_playwright() as p:
        b=await p.chromium.launch();pg=await b.new_page(viewport={'width':794,'height':1123})
        await pg.goto('file:///home/claude/piano/p.html');await pg.wait_for_timeout(600)
        await pg.pdf(path='/home/claude/piano/ZombieSafeHouse_Piano_sponsor_investitori.pdf',format='A4',print_background=True,margin={'top':'0','bottom':'0','left':'0','right':'0'})
        await b.close()
asyncio.run(main())
